import type { Metadata } from "next";
import { notFound } from "next/navigation";
import getCacheData from "@/services/filterPageServiceCache";
import { getPostsByLocation } from "@/services/blog";
import getTourCategoryPageDetail from "@/services/tour-category-pages/getDetail";
import getAllData from "@/services/tour-category-pages/getAllList";
import Page from "@/components/tour-category-page/page";

export const dynamicParams = true;
export const dynamic = "force-static";

export const generateStaticParams = async () => {
  if (process.env.SERVER !== "production") return [];

  const list = await getAllData();

  return list.data.map((page: any) => ({
    slug: page.pageUrl,
  }));
};

export async function generateMetadata({
  params,
}: {
  params: { slug: string };
}): Promise<Metadata> {
  try {
    var tourCategoryPage = await getTourCategoryPageDetail({
      params: { slug: params.slug },
    });
    // Pasif sayfalarda API redirect cevabı döner (data yok) → metadata üretme.
    if (!tourCategoryPage || !tourCategoryPage.data) throw new Error();
  } catch (error) {
    return {};
  }

  return {
    title: tourCategoryPage.data.metaTitle + " - TravelShop Booking",
    description: tourCategoryPage.data.metaDescription,
    alternates: {
      canonical:
        tourCategoryPage.data.canonicalUrl ??
        "https://travelshopbooking.com/" + params.slug,
    },
  };
}

export default async function TourCategoryPage({
  params,
}: {
  params: { slug: string };
}) {
  try {
    var tourCategoryPage = await getTourCategoryPageDetail({
      params: { slug: params.slug },
    });
    if (!tourCategoryPage) throw new Error();
  } catch (error) {
    return notFound();
  }

  if (!tourCategoryPage.data) return notFound();

  var pageParams = {
    title: tourCategoryPage.data.pageTitle,
    pageUrl: tourCategoryPage.data.pageUrl,
    breadcrumbTitle: tourCategoryPage.data.breadcrumbTitle,
    shortDescription: tourCategoryPage.data.pageShortDescription,
    longDescription: tourCategoryPage.data.pageLongDescription,
    destination: tourCategoryPage.data.paramDestination,
    category: tourCategoryPage.data.paramCategory,
    company: "",
    pageType: tourCategoryPage.data.pageCategoryType,
    image: tourCategoryPage.data.image,
    parentCategories: tourCategoryPage.data.parentCategories.map(
      (item: any) => ({
        pageTitle: item.breadcrumbTitle,
        pageUrl: `/${item.pageUrl}`,
      }),
    ),
    // pageTitle = kısa başlık (sticky bar chip'leri), fullTitle = tam sayfa başlığı.
    // Footer link blokları fullTitle kullanır: "City Sightseeing Tours" yerine
    // "Greece City Sightseeing Tours" — anchor text'in tek başına anlamlı olması için.
    categories: tourCategoryPage.data.categories.map((item: any) => ({
      pageTitle: item.breadcrumbTitle,
      fullTitle: item.pageTitle,
      pageUrl: `/${item.pageUrl}`,
      category: item.paramCategory,
      tourCount: item.tourCount,
    })),
    pages: tourCategoryPage.data.pages.map((item: any) => ({
      pageTitle: item.breadcrumbTitle,
      fullTitle: item.pageTitle,
      pageUrl: `/${item.pageUrl}`,
      category: item.paramCategory,
      tourCount: item.tourCount,
    })),
    destinations: (tourCategoryPage.data.destinations ?? []).map((item: any) => ({
      pageTitle: item.breadcrumbTitle,
      fullTitle: item.pageTitle,
      pageUrl: `/${item.pageUrl}`,
      tourCount: item.tourCount,
    })),
    // 'pages' listesinin gerçek ebeveyni: şehir+kategori sayfasında doğrudan
    // ebeveyn (şehir) değil, bir üst seviye (ülke) olur.
    pagesParentTitle: tourCategoryPage.data.pagesParent?.pageTitle ?? null,
    cities: tourCategoryPage.data.cities.map((item: any) => ({
      pageTitle: item.breadcrumbTitle,
      pageUrl: `/${item.pageUrl}`,
      locationId: item.paramLocationId,
    })),
    childPages: tourCategoryPage.data.childCategories
      .filter((item: any) => !item.paramCategory)
      .map((item: any) => ({
        pageTitle: item.breadcrumbTitle,
        fullTitle: item.pageTitle,
        pageUrl: `/${item.pageUrl}`,
        location: item.paramDestination,
        tourCount: item.tourCount,
      })),
    childCategories: tourCategoryPage.data.childCategories
      .filter((item: any) => item.paramCategory)
      .map((item: any) => ({
        pageTitle: item.breadcrumbTitle,
        fullTitle: item.pageTitle,
        pageUrl: `/${item.pageUrl}`,
        category: item.paramCategory,
        tourCount: item.tourCount,
      })),
    faq: tourCategoryPage.data.faq ?? null,
  };

  const [fetchData, guides] = await Promise.all([
    getCacheData(pageParams.pageUrl),
    getPostsByLocation(tourCategoryPage.data.paramLocationId ?? 0),
  ]);

  return <Page params={pageParams} tourData={fetchData} guides={guides} />;
}
