export default async function getCacheData(pageUrl: string) {
    const res = await fetch(
        "https://tsgroup.s3.amazonaws.com/cache/tour-list-pages/" + pageUrl + ".json",
        {
            cache: "force-cache",
            method: "GET",
            headers: {
                "Content-type": "application/json",
                "Content-Language": "en",
                "Accept": "*/*",
                "Accept-Encoding": "gzip, deflate, br",
                "Origin": "https://travelshopbooking.com",
            },
        }
    );


    if (!res.ok)
        throw new Error("Failed to fetch data");

    return res.json();
}